import { gsap } from 'gsap';
import { SplitText } from 'gsap/SplitText';
gsap.registerPlugin(SplitText);
export async function heroLineReveal(el) {
  await document.fonts.ready;
  const split = SplitText.create(el, { type: 'lines', mask: 'lines' });
  gsap.set(el, { opacity: 1 });
  return gsap.from(split.lines, { yPercent: 100, duration: 1, ease: 'expo.out', stagger: 0.1 });
}

export function scramble(el, duration = 500, delay = 0) {
  const clean = el.dataset.clean ?? (el.dataset.clean = el.textContent);
  const pool = /^\d+$/.test(clean) ? '0123456789' : 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const keep = new Set([' ', '/', '?', ',', '.']);
  const ease = (t) => -(Math.cos(Math.PI * t) - 1) / 2; // sine in-out
  const id = (el._scrambleId = (el._scrambleId || 0) + 1);
  let start, lastFrame = 0;
  const frame = (now) => {
    if (id !== el._scrambleId) return;
    start ??= now + delay;
    const t = Math.min(Math.max((now - start) / duration, 0), 1);
    if (now - lastFrame >= 50 || t === 1) {
      lastFrame = now;
      const from = Math.round(ease(t) * clean.length);
      el.textContent = clean.split('').map((c, i) => (i < from || keep.has(c)) ? c : (() => { const r = pool[Math.floor(Math.random() * pool.length)]; return c === c.toLowerCase() ? r.toLowerCase() : r; })()).join('');
    }
    if (t < 1) requestAnimationFrame(frame); else el.textContent = clean;
  };
  requestAnimationFrame(frame);
}

import { gsap } from 'gsap';
export const ruleDraw = (el, delay = 0, duration = 1.5) =>
  gsap.fromTo(el, { scaleX: 0, transformOrigin: '0% 50%' }, { scaleX: 1, duration, ease: 'expo.out', delay });

import { gsap } from 'gsap';
export function slideInFromStart(els, { baseDelay = 0.2, stagger = 0.1, duration = 1 } = {}) {
  return gsap.fromTo(els, { xPercent: -10, opacity: 0 }, { xPercent: 0, opacity: 1, duration, ease: 'expo.out', delay: baseDelay, stagger });
}
export function onceInView(el, cb, threshold = 0.05) {
  const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) { cb(); io.disconnect(); } }, { threshold });
  io.observe(el);
}

import { gsap } from 'gsap';
export function retractOut(rule, content, delay = 0) {
  gsap.set(rule, { transformOrigin: '100% 50%' });
  return gsap.timeline({ delay })
    .to(rule, { scaleX: 0, duration: 0.7, ease: 'expo.out' }, 0)
    .to(content, { xPercent: 10, opacity: 0, duration: 0.7, ease: 'expo.out' }, 0);
}

import Lenis from 'lenis';
export function scrollCoupledHeader(header, lenis, { downRate = 0.5 } = {}) {
  let hidden = 0, last = 0;
  lenis.on('scroll', ({ scroll }) => {
    const h = header.offsetHeight, s = Math.max(0, scroll);
    let d = s - last; if (d > 0 && innerWidth > 768) d *= downRate;
    hidden = Math.min(1, Math.max(0, hidden + d / h)); last = s;
    const y = -h * hidden;
    header.style.transform = `translate3d(0,${y}px,0)`;
    document.documentElement.style.setProperty('--header-offset', `${h + y}px`);
    header.toggleAttribute('data-frosted', s > 30);
  });
}

import { gsap } from 'gsap';
export function setFrost(header, on, mode = 'light') {
  gsap.to(header, { '--frosted': on ? 1 : 0, '--background-opacity': on ? (mode === 'solid' ? 1 : 0.5) : 0, duration: 0.3, ease: 'power2.out' });
}
