import { gsap } from 'gsap';
export function openPanel(wrapper, panels, next) {
  panels.forEach((p) => p !== next && gsap.to(p, { opacity: 0, duration: 0.5, ease: 'power2.out', onComplete: () => (p.hidden = true) }));
  next.hidden = false;
  gsap.fromTo(next, { opacity: 0 }, { opacity: 1, duration: 0.5, delay: 0.1, ease: 'power2.out' });
  gsap.to(wrapper, { height: next.offsetHeight, duration: 0.5, ease: 'power2.out' });
  wrapper.setAttribute('aria-hidden', 'false');
}
export function closePanel(wrapper, panels) {
  panels.forEach((p) => gsap.to(p, { opacity: 0, duration: 0.5, ease: 'power2.out', onComplete: () => (p.hidden = true) }));
  gsap.to(wrapper, { height: 0, duration: 0.5, ease: 'power2.out', onComplete: () => wrapper.setAttribute('aria-hidden', 'true') });
}

import { gsap } from 'gsap';
export function dimSiblings(items, active) {
  items.forEach((el) => gsap.to(el, active && el !== active ? { opacity: 0.5, duration: 0.5, ease: 'power2.out' } : { opacity: 1, duration: active ? 0.15 : 0.5, delay: active ? 0 : 0.15, ease: 'power2.out' }));
}

import { gsap } from 'gsap';
export const scrimIn = (el) => { el.hidden = false; return gsap.fromTo(el, { opacity: 0 }, { opacity: 1, duration: 0.6, ease: 'power2.out' }); };
export const scrimOut = (el) => gsap.fromTo(el, { opacity: 0.5 }, { opacity: 0, duration: 0.3, ease: 'power2.out', onComplete: () => (el.hidden = true) });

