import { gsap } from 'gsap';
export function rowFill(row, bg, on) {
  if (matchMedia('(max-width: 768px)').matches || row.getAttribute('aria-expanded') === 'true') on = false;
  gsap.to(bg, { scaleY: on ? 1 : 0, transformOrigin: '50% 100%', duration: 0.3, ease: 'sine.out' });
  gsap.to(row, { '--filter-progress': on ? 1 : 0, duration: 0.3, ease: 'sine.out' });
  row.classList.toggle('is-filled', on);
}

import { gsap } from 'gsap';
export function toggleRow(row, header, content, thumbs = []) {
  const open = row.getAttribute('aria-expanded') !== 'true';
  row.setAttribute('aria-expanded', String(open));
  const h = header.getBoundingClientRect().height, c = content.scrollHeight;
  gsap.to(content, { height: open ? c : 0, duration: 0.5, ease: 'sine.out' });
  gsap.to(row, { height: open ? h + c : h, duration: 0.5, ease: 'sine.out' });
  gsap.to(thumbs, open ? { opacity: 1, duration: 0.25, stagger: 0.05, ease: 'sine.out' } : { opacity: 0, duration: 0.1, ease: 'sine.out' });
}

import { gsap } from 'gsap';
export function bindCardDisclosure(card, desc, icons, scramble) {
  const show = () => { gsap.fromTo(desc, { height: 0, marginTop: 0, opacity: 0 }, { height: '1.25rem', marginTop: '0.5rem', opacity: 1, duration: 0.5, ease: 'power2.out' }); gsap.to(icons, { opacity: 1, duration: 0.5, ease: 'power2.out' }); scramble?.(desc, 750); };
  const hide = () => { gsap.to(desc, { height: 0, marginTop: 0, opacity: 0, duration: 0.5, ease: 'power2.out' }); gsap.to(icons, { opacity: 0, duration: 0.5, ease: 'power2.out' }); };
  if (matchMedia('(hover: hover)').matches) { card.addEventListener('mouseenter', show); card.addEventListener('mouseleave', hide); }
  else new IntersectionObserver(([e], o) => { if (e.isIntersecting) { show(); o.disconnect(); } }, { threshold: 0.05 }).observe(card);
}

