import { gsap } from 'gsap';
export function openModal(root, scrim, closeBtn, lenis) {
  lenis?.stop(); root.hidden = false;
  gsap.fromTo(root, { backdropFilter: 'blur(0px)' }, { backdropFilter: 'blur(30px)', duration: 1, ease: 'sine.out' });
  gsap.fromTo(scrim, { opacity: 0 }, { opacity: 0.7, duration: 1, ease: 'sine.out', onComplete: () => closeBtn.focus() });
}
export function closeModal(root, scrim, lenis) {
  lenis?.start();
  gsap.to(scrim, { opacity: 0, duration: 1, ease: 'sine.out' });
  gsap.to(root, { backdropFilter: 'blur(0px)', duration: 1, ease: 'sine.out', onComplete: () => (root.hidden = true) });
}

import { gsap } from 'gsap';
const T = { duration: 0.25, ease: 'power1.inOut' };
export function openSide(root, panel, scrim, focusEl) { root.hidden = false; gsap.fromTo(panel, { xPercent: 100, x: 0 }, { xPercent: 0, ...T }); gsap.to(scrim, { opacity: 0.7, ...T }); gsap.fromTo(root, { backdropFilter: 'blur(0px)' }, { backdropFilter: 'blur(30px)', ...T, onComplete: () => focusEl.focus() }); }
