import { gsap } from 'gsap';
export async function transitionOut({ overlay, oldPage, lenis }) {
  const y = lenis.scroll;
  gsap.set(oldPage, { position: 'fixed', top: -y, left: 0, right: 0, transformOrigin: `50vw ${y + innerHeight / 2}px` });
  lenis.scrollTo(0, { immediate: true, force: true });
  gsap.set(overlay, { autoAlpha: 0 });
  await Promise.all([gsap.to(oldPage, { scale: 1.02, duration: 0.35, ease: 'sine.out' }), gsap.to(overlay, { autoAlpha: 1, duration: 0.35, ease: 'sine.out' })]);
}

import { gsap } from 'gsap';
export async function transitionIn({ overlay, newPage }) {
  gsap.set(newPage, { scale: 0.98, visibility: 'visible' });
  await Promise.all([gsap.to(newPage, { scale: 1, duration: 0.35, ease: 'sine.in', clearProps: 'transform' }), gsap.to(overlay, { autoAlpha: 0, duration: 0.35, ease: 'sine.in' })]);
}

import Lenis from 'lenis';
export const lenis = new Lenis({ lerp: 0, duration: 0.8, easing: (t) => 1 - Math.pow(1 - t, 4), smoothWheel: true, syncTouch: false, autoRaf: true });
export const scrollToNext = (section) => lenis.scrollTo(section.offsetTop + section.offsetHeight, { duration: 2.5 });

import { gsap } from 'gsap';
export function slider(track, count, w) {
  let i = 0, x = 0, startX = 0, base = 0, lastX = 0, lastT = 0, v = 0;
  const clampF = (val) => { const min = -w * (count - 1); return val > 0 ? val * 0.3 : val < min ? min + (val - min) * 0.3 : val; };
  const go = (n) => { i = Math.max(0, Math.min(count - 1, n)); gsap.to(track, { x: -w * i, duration: 0.5, ease: 'power2.out', onUpdate: () => (x = gsap.getProperty(track, 'x')) }); };
  track.addEventListener('pointerdown', (e) => { gsap.killTweensOf(track); startX = lastX = e.clientX; base = x; lastT = performance.now(); track.setPointerCapture(e.pointerId); });
  track.addEventListener('pointermove', (e) => { if (!track.hasPointerCapture(e.pointerId)) return; const now = performance.now(); v = (e.clientX - lastX) / Math.max(1, now - lastT) * 16; lastX = e.clientX; lastT = now; x = clampF(base + e.clientX - startX); gsap.set(track, { x }); });
  track.addEventListener('pointerup', () => { const dir = -Math.sign(v); if (Math.abs(v) > 1.5) go(Math.round(-x / w) + dir * Math.round(Math.log2(Math.abs(v)))); else if (Math.abs(v) > 0.1) go(i + dir); else go(Math.round(-x / w)); });
  addEventListener('keydown', (e) => { if (e.key === 'ArrowLeft') go(i - 1); if (e.key === 'ArrowRight') go(i + 1); });
  return { next: () => go(i + 1), prev: () => go(i - 1) };
}

import { gsap } from 'gsap';
// markup: .roller > .col (x N) > .digit (0..9 repeated twice), .roller{overflow:hidden;height:1lh} .digit{height:1lh}
export function rollTo(root, value, duration = 1) {
  const cols = [...root.querySelectorAll('.col')];
  const digits = String(value).padStart(cols.length, '0').split('').map(Number);
  return gsap.timeline().add(cols.map((c, k) => gsap.to(c, { yPercent: -100 * (digits[k] + 10) / 20, duration, ease: 'expo.out' })), 0);
}

