import { gsap } from 'gsap';
export function drawChart(lines, labels, markers, enabled = !matchMedia('(prefers-reduced-motion: reduce)').matches) {
  if (!enabled) return;
  lines.forEach((l) => { const len = l.getTotalLength(); gsap.fromTo(l, { strokeDasharray: len, strokeDashoffset: -len }, { strokeDashoffset: 0, duration: 1.5, ease: 'expo.out' }); });
  gsap.fromTo(labels, { opacity: 0 }, { opacity: 1, duration: 1, ease: 'expo.out', stagger: 0.2, delay: 0.5 });
  gsap.fromTo(markers, { opacity: 0 }, { opacity: 1, duration: 0.5, ease: 'power2.out', stagger: 0.05, delay: 0.8 });
}

// Minimal DOM-to-canvas sync (three.js or any WebGL renderer)
export function syncMeshToElement(mesh, el, viewportH) {
  const r = el.getBoundingClientRect();
  mesh.visible = r.bottom > 0 && r.top < viewportH;
  mesh.material.uniforms.uVertOffset.value = r.top / viewportH;
  mesh.material.uniforms.uVertClip.value = Math.min(1, Math.max(0, (Math.min(r.bottom, viewportH) - Math.max(r.top, 0)) / r.height));
}
